export const PROGRESS_KEY='musicquest-progress-v1';
export function parseProgress(text,knownIds){
 const p=JSON.parse(text);
 if(!p||p.app!=='MusicQuest'||p.version!==1||!Array.isArray(p.completed)||!Array.isArray(p.passed)||[...p.completed,...p.passed].some(id=>typeof id!=='string'))throw new Error('Choose a MusicQuest version 1 progress export with lesson-ID lists.');
 const known=id=>!knownIds||knownIds.has(id),passed=new Set(p.passed.filter(known)),completed=new Set(p.completed.filter(id=>known(id)&&passed.has(id)));
 return {passed,completed,epoch:typeof p.epoch==='string'?p.epoch:'legacy',ignored:[...p.completed,...p.passed].filter(id=>!known(id)).length};
}
export function createProgressStore({storage,locks,knownIds,onChange=()=>{},makeEpoch=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random()}`}={}){
 let state={enabled:false,passed:new Set(),completed:new Set(),epoch:null},queue=Promise.resolve();
 const snapshot=()=>({...state,passed:new Set(state.passed),completed:new Set(state.completed)});
 const read=()=>{const raw=storage.getItem(PROGRESS_KEY);return raw===null?null:parseProgress(raw,knownIds)};
 const emit=message=>{onChange(snapshot(),message,true);return {ok:true,message,state:snapshot()}};
 const fail=message=>{onChange(snapshot(),message,false);return {ok:false,message,state:snapshot()}};
 const record=s=>({app:'MusicQuest',version:1,completed:[...s.completed],passed:[...s.passed],epoch:s.epoch});
 const write=s=>storage.setItem(PROGRESS_KEY,JSON.stringify(record(s)));
 const merge=(a,b)=>({passed:new Set([...a.passed,...b.passed]),completed:new Set([...a.completed,...b.completed])});
 const freshForAction=()=>{if(!state.enabled)return;const fresh=read();if(!fresh){state.enabled=false;state.epoch=null;return}state=fresh.epoch===state.epoch?{enabled:true,epoch:fresh.epoch,...merge(state,fresh)}:{enabled:true,epoch:fresh.epoch,passed:fresh.passed,completed:fresh.completed}};
 const exclusive=fn=>{const run=()=>locks?.request?locks.request('musicquest-progress-write',fn):fn();const task=queue.then(run,run).catch(()=>fail('The progress action could not finish. Your session remains available; export a backup.'));queue=task.catch(()=>{});return task};
 function initialize(){try{const saved=read();if(saved)state={enabled:true,epoch:saved.epoch,passed:saved.passed,completed:saved.completed};return emit('')}catch{return fail('Saved progress could not be read. It has not been deleted. You can still learn and export session progress.')}}
 async function update(kind,id){return exclusive(()=>{try{freshForAction()}catch{return fail('Browser storage could not be read; progress was not changed. Export a backup before trying again.')}const next=snapshot();if(kind==='pass')next.passed.add(id);if(kind==='complete'&&next.passed.has(id))next.completed.add(id);state=next;if(state.enabled){try{write(state)}catch{return fail('Progress updated for this session, but could not be saved. Export a backup before leaving.')}}return emit(state.enabled?'Progress saved in this browser.':'Progress updated for this session only.');})}
 async function setEnabled(enabled){return exclusive(()=>{if(!enabled){try{freshForAction();storage.removeItem(PROGRESS_KEY);state.enabled=false;state.epoch=null;return emit('Saving is off; session progress remains until you leave.')}catch{return fail('Could not turn off browser saving. The previous saved data may still remain; please try again.')}}try{const saved=read(),base=state.enabled&&saved&&state.epoch!==saved.epoch?saved:state,next={enabled:true,epoch:saved?.epoch||makeEpoch(),...merge(base,saved||{passed:new Set(),completed:new Set()})};write(next);state=next;return emit('Saving in this browser is on.')}catch{return fail('Browser saving could not be enabled. Your session progress is unchanged; export a backup.')}})}
 async function clear(){return exclusive(()=>{try{freshForAction();const next={enabled:state.enabled,epoch:state.enabled?makeEpoch():null,passed:new Set(),completed:new Set()};if(next.enabled)write(next);else storage.removeItem(PROGRESS_KEY);state=next;return emit(state.enabled?'Saved and session progress cleared.':'MusicQuest progress cleared; saving remains off.')}catch{return fail('Could not clear saved progress. Existing progress has been kept; please try again.')}})}
 async function importText(text){let incoming;try{incoming=parseProgress(text,knownIds)}catch(e){return fail('Import failed: '+e.message)}return exclusive(()=>{try{freshForAction()}catch{return fail('Import could not read browser storage. Existing progress has been kept.')}state={...state,...merge(state,incoming)};if(state.enabled){try{write(state)}catch{return fail('Import merged into this session, but saving failed. Existing progress is kept; export a backup.')}}return emit(`Progress imported and merged; existing progress kept.${incoming.ignored?' Unknown lesson IDs were ignored.':''}${state.enabled?' Saved in this browser.':' Session only; saving is off.'}`)})}
 function refreshFromStorage(){try{const saved=read();if(saved&&!state.enabled)return emit('Saved progress changed in another tab. This tab remains session-only; enable saving here to merge its progress.');if(!saved){state.enabled=false;state.epoch=null;return emit('Browser saving was turned off in another tab. Session progress is still available.')}state=state.enabled&&state.epoch===saved.epoch?{enabled:true,epoch:saved.epoch,...merge(state,saved)}:{enabled:true,epoch:saved.epoch,passed:saved.passed,completed:saved.completed};return emit('Progress refreshed from another tab.')}catch{return fail('Progress from another tab could not be read. Your current session is unchanged.')}}
 return {initialize,snapshot,pass:id=>update('pass',id),complete:id=>update('complete',id),setEnabled,clear,importText,refreshFromStorage,exportData:()=>({app:'MusicQuest',version:1,completed:[...state.completed],passed:[...state.passed]})};
}
